  String _drawerQuery = '';
  final TextEditingController _drawerSearchController = TextEditingController();

  /// The empty state's Clear affordance: reset the query and the field —
  /// the full list restores instantly.
  void _clearDrawerSearch() {
    setState(() => _drawerQuery = '');
    _drawerSearchController.clear();
  }

  /// Session id → on-disk header (the `agent`/`parent` classification
  /// source for the drawer's session tree, issue #198), from the last
  /// listing.
  Map<String, SessionMetadata> _metadataById = const {};

  /// Parent session ids the user expanded in the drawer's tree — the
  /// SAME model as the wide sidebar (groups within the auto-expand limit
  /// render open; an active descendant forces its parent open).
  final Set<String> _expandedParents = {};

  /// Parent ids the user explicitly COLLAPSED (issue #426) — small
  /// groups default open, so closing one must stick.
  final Set<String> _collapsedParents = {};

  /// The session the user just tapped (an open is in flight): its row
  /// highlights AND sorts to the top immediately — the SAME rule the wide
  /// sidebar applies. Cleared once the manager's live id / active slot
  /// catches up with the attach broadcast (see [_onManagerChanged]).
  String? _pendingOpenId;

  /// Last seen live-session count — drives the persisted-list resync in
  /// [_onManagerChanged].
  var _lastLiveCount = -1;

  /// Key on the always-rendered bar column — its natural height is measured
  /// live into [_barHeight] so the drawer list and the panel transcript can
  /// pad their bottoms by the REAL bar height (composer + safe area +
  /// optional streaming status row) in the current environment.
  final GlobalKey _barKey = GlobalKey();

  /// Last measured natural bar height; seeded with an estimate.
  double _barHeight = 96;

  /// The interactive handler trio (approval dialog, ask sheets,
  /// secret-request sheets) bound to this sheet's context. The sheet is
  /// the PRIMARY chat surface on narrow layouts (the extension panel!):
  /// without this binding approvals had no handler, every gated tool
  /// call stalled out the service-worker's 120s backstop and was denied
  /// with the user never asked — "busy" badge, no output, and no dialog
  /// to answer.
  late final FaChatSurfaceHandlers _surfaceHandlers = FaChatSurfaceHandlers(
    context: context,
  );

  /// The auth-expired card's action: a CodeMie SSO session died mid-chat
  /// (the API call came back as the SSO login page) — re-run the platform
  /// sign-in flow. On the extension this opens the CodeMie login tab and
  /// polls the shared cookie jar; on desktop/mobile the full SSO flow.
  Future<void> _onAuthRecovery(String providerId) async {
    if (providerId != 'codemie') return;
    final ok = await runCodemieSsoFlow(
      context: context,
      registry: widget.registry ?? ProviderRegistry.inMemory(),
      service: _activeService,
      lastConnectionStore:
          widget.lastConnectionStore ?? LastConnectionStore.inMemory(),
    );
    if (!mounted) return;
    _announceAuthRecovery(ok);
  }

  /// The re-auth outcome snack (gh-1848 split).
  void _announceAuthRecovery(bool ok) {
    ok
        ? showFahSnack(
            context,
            'Authorization successful — try sending your message again.',
          )
        : showFahErrorSnack(context, 'Authorization cancelled.');
  }

  List<FlutterManagedSession> get _liveSessions => widget.manager.sessions;

  AgentService? get _activeService => widget.manager.active?.service;

  @override
  void initState() {
    super.initState();
    _panelAnim = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 260),
    );
    _drawerAnim = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 220),
    );
    _namesStore = widget.sessionNamesStore;
    _namesStore?.addListener(_onChanged);
    if (_namesStore == null) unawaited(_loadNamesStore());
    widget.manager.addListener(_onManagerChanged);
    // The header's model chip follows the ACTIVE service (reconfigure,
    // session restore) — the manager alone never notifies on those.
    _subscribeToActiveService();
    unawaited(_reloadPersisted());
    // Issue #381: boot skipped an oversized last-active session — say so
    // instead of the old silent swap; the action opens it windowed.
    showBootOversizeNotice(
      context,
      manager: widget.manager,
      names: _namesStore,
      onOpen: (metadata) => _openPersisted(metadata),
    );
    // Live-session presence: sessions a `fa` CLI currently owns show a
    // green dot and attach (read-only view + input hand-over) on tap.
    _presence = CliSessionPresence.start(
      widget.manager.env,
      widget.manager.sessionsRoot,
    );
    // A presence change (a CLI started or exited) must resync the drawer:
    // new CLI sessions come from disk, exited ones lose their dot.
    _presence?.addListener(_onPresenceChanged);
    // Disk sessions appear (a CLI created one) without any manager event
    // — poll the listing so the drawer stays current while the app runs.
    _persistedTimer = Timer.periodic(const Duration(seconds: 3), (_) {
      if (mounted) unawaited(_reloadPersisted());
    });
    // SizeChangedLayoutNotifier does NOT fire for the FIRST layout — it
    // only reports changes against the baseline — so measure the bar once
    // up front; later changes (streaming row, multiline field) come through
    // the notification.
    WidgetsBinding.instance.addPostFrameCallback((_) => _measureBarHeight());
    // Apps↔chat surface mode (issue #224): restore the persisted toggle
    // state once — chat expanded by default on a first run.
    if (widget.restoreAppsMode) unawaited(_restoreAppsMode());
  }

  /// Loads the persisted mode and jumps the panel to it (no boot
  /// animation). A toggle that already happened wins over the file.
  Future<void> _restoreAppsMode() async {
    final mode = await AppsHomeModeStore.load(widget.manager.env);
    if (!mounted || _userToggledApps) return;
    _appsMode = mode;
    _panelAnim.value = mode.chatExpanded ? 1 : 0;
  }

  /// Reads the bar's real laid-out height into [_barHeight] (no-op when
  /// unchanged). Must run post-frame — during layout the render object is
  /// still dirty.
  void _measureBarHeight() {
    if (!mounted) return;
    final h = _barKey.currentContext?.size?.height;
    if (h != null && (h - _barHeight).abs() > 0.5) {
      setState(() => _barHeight = h);
    }
  }

  @override
  void dispose() {
    _surfaceHandlers.detach();
    widget.manager.removeListener(_onManagerChanged);
    _listenedService?.removeListener(_onChanged);
    _namesStore?.removeListener(_onChanged);
    _presence?.removeListener(_onPresenceChanged);
    _presence?.dispose();
    _persistedTimer?.cancel();
    _panelAnim.dispose();
    _drawerAnim.dispose();
    _drawerSearchController.dispose();
    super.dispose();
  }

  void _onChanged() {
    if (mounted) setState(() {});
  }

  /// The service we're currently listening to — the header's model chip
  /// rebuilds on model changes (reconfigure, session restore), which the
  /// manager's own notifications never cover. Same pattern as the wide
  /// shell.
  AgentService? _listenedService;

  void _subscribeToActiveService() {
    final active = widget.manager.active?.service;
    if (active == _listenedService) return;
    _listenedService?.removeListener(_onChanged);
    _listenedService = active;
    active?.addListener(_onChanged);
  }

  /// Presence transitions resync both the live dots and the disk listing
  /// (a CLI session appears on start; an exited one may reappear as a
  /// persisted entry).
  void _onPresenceChanged() {
    if (!mounted) return;
    unawaited(_reloadPersisted());
    setState(() {});
  }

  Future<void> _loadNamesStore() async {
    final service = _activeService;
    if (service == null) return;
    final store =
        service.namesStoreOverride ??
        await SessionNamesStore.shared(service.env);
    if (!mounted || _namesStore != null) return;
    setState(() => _namesStore = store..addListener(_onChanged));
  }

  /// The disk-persisted sessions minus the live ones, for the drawer list.
  Future<void> _reloadPersisted() async {
    final service = _activeService;
    if (service == null) return;
    try {
      final all = await service.listSessions();
      final liveIds = _liveSessions.map((s) => s.id).toSet();
      final persisted = drawerPersistedSessions(
        all: all,
        liveIds: liveIds,
        relayLiveId: service.liveSessionId,
      );
      final rowIds = all.map((m) => m.id).toSet();
      final rowIdsChanged =
          rowIds.length != _lastDrawerRowIds.length ||
          !rowIds.every(_lastDrawerRowIds.contains);
      if (rowIdsChanged) {
        _lastDrawerRowIds = rowIds;
        debugPrint(
          '[fah][drawer] sessions: ${all.length} rows '
          '(live=${service.liveSessionId ?? '-'}, '
          'archived=${persisted.length})',
        );
      }
      final selection =
          '[fah][drawer] selection: selected=${_selectedSessionId ?? '-'} '
          'hostedLive=${widget.manager.hostedLiveId.value ?? '-'} '
          'active=${widget.manager.activeId ?? '-'} '
          'slots=${_liveSessions.map((s) => s.id).join(',')}';
      if (selection != _lastSelectionLog) {
        _lastSelectionLog = selection;
        debugPrint(selection);
      }
      if (mounted) {
        setState(() {
          _persisted = persisted;
          _createdAtById = {for (final m in all) m.id: m.createdAt};
          _updatedAtById = {
            for (final m in all)
              if (m.lastUpdatedAt != null) m.id: m.lastUpdatedAt!,
          };
          _cwdById = {for (final m in all) m.id: m.cwd};
          _metadataById = {for (final m in all) m.id: m};
        });
      }
    } on Object {
      // A broken sessions dir must not break the sheet.
    }
  }

  /// The ONE selected id every drawer row compares against — the same
  /// rule as the wide sidebar's `_selectedSessionId`: the click's pending
  /// id wins while in flight, then the SW's live id (hosted), then the
  /// manager's active slot. Pending is REPLACEMENT, not additive —
  /// exactly one row can ever be highlighted.
  String? get _selectedSessionId {
    final pending = _pendingOpenId;
    if (pending != null) return pending;
    return widget.manager.hostedLiveId.value ?? widget.manager.activeId;
  }

  /// External session changes (drawer open, another surface's switch):
  /// drop persisted entries that went live, resync the list on live-count
  /// changes (closed sessions reappear there) and rebuild.
  void _onManagerChanged() {
    if (!mounted) return;
    _subscribeToActiveService();
    if (_pendingOpenId != null &&
        (widget.manager.hostedLiveId.value == _pendingOpenId ||
            widget.manager.activeId == _pendingOpenId)) {
      _pendingOpenId = null; // the broadcast landed — the real id took over
    }
    final liveIds = _liveSessions.map((s) => s.id).toSet();
    final filtered = [
      for (final m in _persisted)
        if (!liveIds.contains(m.id)) m,
    ];
    if (filtered.length != _persisted.length) {
      _persisted = filtered;
      _opening.removeAll(liveIds);
    }
    if (liveIds.length != _lastLiveCount) {
      _lastLiveCount = liveIds.length;
      unawaited(_reloadPersisted());
    }
    setState(() {});
  }

  // --- panel open/close ------------------------------------------------------

  /// Opens the session panel programmatically (the launcher's session chip,
  /// the composer's onSent, the streaming status row).
  void expand() => unawaited(_openPanel());

  Future<void> _openPanel() {
    _userToggledApps = true;
    unawaited(_appsMode?.setChatExpanded(true));
    AppAnalytics.instance.chatSheetState('expanded');
    if (_drawerAnim.value > 0) {
      unawaited(
        _drawerAnim.animateTo(
          0,
          duration: const Duration(milliseconds: 200),
          curve: Curves.easeInCubic,
        ),
      );
    }
    return _panelAnim.animateTo(1, curve: Curves.easeOutCubic);
  }

  Future<void> _closePanel() {
    _userToggledApps = true;
    unawaited(_appsMode?.setChatExpanded(false));
    AppAnalytics.instance.chatSheetState('collapsed');
    // Dismiss the keyboard together with the panel: a still-focused
    // composer in the docked bar would keep the keyboard floating over the
    // app grid with no visible way to get rid of it.
    FocusManager.instance.primaryFocus?.unfocus();
    return _panelAnim.animateTo(
      0,
      duration: const Duration(milliseconds: 220),
      curve: Curves.easeInCubic,
    );
  }

  /// The laid-out height of the sheet's stack (below the status bar, above
  /// the keyboard), updated from the [LayoutBuilder] on every layout. Drives
  /// the drag math via [_panelPixels].
  double _stackHeight = 0;

  double get _panelPixels => _stackHeight * widget.panelFraction;

  void _onPanelDragUpdate(DragUpdateDetails details) {
    final pixels = _panelPixels;
    if (pixels <= 0) return; // not laid out yet — ignore the drag
    _panelAnim.stop();
    _panelAnim.value = (_panelAnim.value - details.delta.dy / pixels).clamp(
      0.0,
      1.0,
    );
  }

  void _onPanelDragEnd(DragEndDetails details) {
    final velocity = details.velocity.pixelsPerSecond.dy;
    if (velocity >= _flingVelocity) {
      unawaited(_closePanel());
    } else if (velocity <= -_flingVelocity) {
      unawaited(_openPanel());
    } else {
      unawaited(_panelAnim.value < 0.5 ? _closePanel() : _openPanel());
    }
  }

  void _onPanelDragCancel() {
    // A canceled gesture (the arena was lost mid-drag) must still settle on
    // a real state — never leave the panel hanging between states.
    unawaited(_panelAnim.value < 0.5 ? _closePanel() : _openPanel());
  }

  // --- drawer ----------------------------------------------------------------

  Future<void> _toggleDrawer() {
    if (_drawerAnim.value > 0.5) {
      // The search is a transient lookup: closing the drawer drops it, so
      // reopening always shows the full list.
      _drawerQuery = '';
      _drawerSearchController.clear();
      return _drawerAnim.animateTo(
        0,
        duration: const Duration(milliseconds: 200),
        curve: Curves.easeInCubic,
      );
    }
    unawaited(_reloadPersisted());
    return _drawerAnim.animateTo(1, curve: Curves.easeOutCubic);
  }

  /// Drawer row tap: live sessions switch in place, persisted ones open
  /// lazily — either way the drawer closes and the panel opens.
  Future<void> _openSessionFromDrawer(String id) async {
    unawaited(_toggleDrawer());
    // A live CLI session attaches (read-only view + input hand-over)
    // instead of opening a second writer on the same JSONL. (No pending
    // highlight: the manager never adopts an attached session.)
    if (_presence?.isLive(id) ?? false) {
      await _attachToCliSession(id);
      if (mounted) unawaited(_openPanel());
      return;
    }
    // The dot moves NOW (same as the wide sidebar's pending id), not a
    // beat later when the SW confirm arrives.
    if (mounted) setState(() => _pendingOpenId = id);
    if (_liveSessions.any((s) => s.id == id)) {
      // Hosted (extension panel / relay shell): the local slot is only the
      // boot attach keyholder — a bare switchTo never re-attaches the
      // transcript and the row tap dead-ends silently. Re-dispatch through
      // the SW so it switches (or re-attaches when already live).
      final relayOpen = _activeService?.openSessionAction;
      if (relayOpen != null) {
        await relayOpen(id);
      } else {
        widget.manager.switchTo(id);
      }
    } else {
      final metadata = _persisted.where((m) => m.id == id).firstOrNull;
      if (metadata != null) await _openPersisted(metadata);
    }
    if (mounted) unawaited(_openPanel());
  }

  /// Attaches to a session owned by a running `fa` CLI: the transcript
  /// follows the session JSONL 1:1 and composer input is handed to the
  /// CLI process through the messaging fabric.
  Future<void> _attachToCliSession(String sessionId) async {
    final metadata = _persisted.where((m) => m.id == sessionId).firstOrNull;
    final title =
        _namesStore?.titleFor(sessionId) ??
        derivedSessionTitle(
          context,
          id: sessionId,
          createdAt: metadata?.createdAt ?? DateTime.now(),
        );
    // Root + slug come from the session file's own path so the fabric
    // mailboxes hit the EXACT root the owning CLI colocated them under —
    // never a guessed default (App Group vs ~/.fah/sessions fallback,
    // multi-root listings, other-workspace sessions).
    final (attachRoot, attachSlug) = sessionRootAndSlugForPath(
      defaultRoot: widget.manager.sessionsRoot,
      sessionPath: metadata?.path,
      fallbackCwd: widget.manager.env.sessionCwd,
    );
    final transport = fileAttachTransport(
      env: widget.manager.env,
      sessionsRoot: attachRoot,
      cwdSlug: attachSlug,
      resolvePath: (id) async => id == sessionId ? metadata?.path : null,
    );
    final controller = AttachedSessionController(
      sessionId: sessionId,
      title: title,
      transport: transport,
    );
    await Navigator.of(context).push(
      MaterialPageRoute<void>(
        builder: (_) => AttachedSessionScreen(controller: controller),
      ),
    );
    controller.dispose();
  }

  /// Lazily opens a persisted session (same config path the old pager used).
  /// `loadSession` restores the session's own effective model (its last
  /// `model_change` record) on top of this config.
  Future<void> _openPersisted(SessionMetadata metadata) async {
    if (!_opening.add(metadata.id)) return;
    try {
      final active = _activeService;
      if (active == null) return;
      // Relay sessions (extension panel): the archive lives in the SW's
      // storage — ask it to restore the session instead of building a
      // local service that cannot read it.
      final relayOpen = active.openSessionAction;
      if (relayOpen != null) {
        await relayOpen(metadata.id);
        return;
      }
      await _openClonedSession(metadata, active);
    } finally {
      _opening.remove(metadata.id);
    }
  }

  /// Opens [metadata] as a clone of the active service, mapping the two
  /// recoverable open failures onto their fallback surfaces (budget snackbar,
  /// viewer attach).
  Future<void> _openClonedSession(
    SessionMetadata metadata,
    AgentService active,
  ) async {
    try {
      await widget.manager.openSession(
        metadata,
        config:
            active.configForClone ??
            AgentConfig(
              providerKind: active.providerKind,
              modelId: active.modelId,
              baseUrl: '',
              apiKey: '',
            ),
        serviceFactory: () async => active.clone(),
      );
    } on SessionTooLargeException {
      _showSessionTooLarge(metadata);
    } on SessionDrivenElsewhereException {
      // Live lease (#428): never a second writer — attach as a viewer
      // (transcript tail; the composer hands over to the driving agent).
      if (!mounted) return;
      await _attachToCliSession(metadata.id);
    }
  }

  /// The over-budget refusal: a snackbar naming the session's size in MB.
  void _showSessionTooLarge(SessionMetadata metadata) {
    if (!mounted) return;
    final sizeMb = (metadata.sizeBytes ?? 0) / (1024 * 1024);
    showFahErrorSnack(
      context,
      context.l10n.sessionTooLargeTitle(sizeMb.toStringAsFixed(0)),
    );
  }

  Future<void> _newSession() async {
    final manager = widget.manager;
    final source = manager.active?.service;
    if (source == null) return;
    // Relay sessions (extension panel) live in the service worker: a new
    // session is a SW-side reset, not a second local session — cloning a
    // config is impossible there (configForClone is null, the old silent
    // no-op).
    final relayReset = source.newSessionAction;
    if (relayReset != null) {
      await relayReset();
      return;
    }
    final config =
        source.configForClone ??
        manager.sessions.firstOrNull?.service.configForClone;
    if (config == null) return;
    await manager.createSession(
      config: config,
      serviceFactory: () async => source.clone(),
    );
  }

  /// Drawer "New session" tile: create, then open the panel on it.
  Future<void> _newSessionFromDrawer() async {
    unawaited(_toggleDrawer());
    await _newSession();
    if (mounted) unawaited(_openPanel());
  }

  /// Single-flight over [mintAndOpenNewSession]: a rapid second trigger
  /// while the clone is in flight must never double-mint (issue #864 E3).
  bool _mintingNew = false;

  /// The Fa entry's long-press (issue #864): mint exactly ONE new session,
  /// make it active, and open the panel on it. Haptic marks the mint (the
  /// tap keeps its silent continue-the-active-session meaning).
  ///
  /// Deliberately NOT [_newSessionFromDrawer]: the entry gesture fires from
  /// the collapsed sheet where the drawer is CLOSED — routing through the
  /// drawer tile's helper would flash the drawer open (its first act is
  /// [_toggleDrawer]) while the clone is in flight (review #1144).
  Future<void> mintAndOpenNewSession() async {
    if (_mintingNew) return;
    _mintingNew = true;
    try {
      // Fire-and-forget: the ack is flow control for nobody, and awaiting
      // a platform channel here deadlocks fake-async widget tests.
      unawaited(HapticFeedback.mediumImpact());
      await _newSession();
      if (mounted) unawaited(_openPanel());
    } on Object catch (error) {
      // The entry gesture fires through unawaited(...) — a raw failure
      // would surface as an unhandled zone error with zero user feedback
      // (review #1144 follow-up). Mirror the app-bound forward's remedy:
      // one log line + a snack; the active session stays untouched.
      AppLog.i('sessions', 'Fa-entry mint failed: $error');
      if (mounted) {
        showFahErrorSnack(context, context.l10n.sessionMintFailed);
      }
    } finally {
      _mintingNew = false;
    }
  }

  Future<void> _openFullChat() async {
    final service = widget.manager.active?.service;
    await Navigator.of(context).push(
      MaterialPageRoute<void>(
        // Rebuild on every service tick (issue #225 review): the header
        // chip and project pill must reflect model switches and folder
        // changes, not the values captured at route push — the wide
        // shell listens the same way.
        builder: (_) => service == null
            ? _buildFullChat(service)
            : ListenableBuilder(
                listenable: service,
                builder: (context, _) => _buildFullChat(service),
              ),
      ),
    );
  }

  /// The pushed full-chat route body (issue #225): the shared surface
  /// with the project identity + quick-model chip inline.
  Widget _buildFullChat(AgentService? service) {
    // Capture the non-null service up front: closures do not benefit
    // from the null-check promotion below.
    final AgentService? active = service;
    final VoidCallback? openPicker;
    final VoidCallback? openSettings;
    if (active == null) {
      openPicker = null;
      openSettings = null;
    } else {
      openPicker = () => unawaited(_openModelPicker(active));
      openSettings = () => unawaited(_openModelSettings(active));
    }
    final modelChip = QuickModelChip(
      key: const ValueKey('fullChatModelChip'),
      modelId: service?.modelId ?? '',
      tooltip: context.l10n.chatModelSwitchTooltip,
      maxWidth: 132,
      // The chip's tap is non-null by contract; without an active
      // service the full chat is unreachable and the tap is a no-op.
      onTap: openPicker ?? () {},
      onLongPress: openSettings,
    );
    return ChatScreen(
      manager: widget.manager,
      registry: widget.registry,
      lastConnectionStore: widget.lastConnectionStore,
      uploadPicker: widget.uploadPicker,
      asr: widget.asr,
      asrTranscriber: widget.asrTranscriber,
      audioControllerFactory: widget.audioControllerFactory,
      videoControllerFactory: widget.videoControllerFactory,
      // The merged adaptive header (issue #225): the full chat renders
      // the same project identity + quick-model chip inline.
      projectIcon: Icons.folder_outlined,
      projectIconColor: _sessionHasFolder(service)
          ? Theme.of(context).colorScheme.primary
          : Theme.of(context).colorScheme.onSurfaceVariant,
      projectLabel: _projectLabel(service),
      modelChip: active == null
          ? modelChip
          : _withQuotaBadge(active, modelChip),
      onModelChipTap: openPicker,
      chipMenuLabel: service?.modelId,
      // The full chat's Apps button (issue #224) pops back here AND
      // collapses the panel, so the tap really lands on the apps grid.
      onAppsToggle: () => unawaited(_closePanel()),
    );
  }

  /// Opens the active session's trajectory ledger (mobile parity,
  /// issue #168): a full-screen pushed page over the shared fa_ui
  /// surface. A route, not a sheet — a deep ledger reads wrong in a
  /// bottom sheet and the route keeps the platform back gesture.
  Future<void> _openTrajectory() async {
    if (_activeService == null) return;
    await Navigator.of(context).push(
      MaterialPageRoute<void>(
        builder: (_) => _SessionTrajectoryPage(manager: widget.manager),
      ),
    );
  }

  /// Whether the active session works inside a mounted project folder
  /// (drives the project pill's indigo tint, mirroring the wide shell).
  bool _sessionHasFolder(AgentService? service) =>
      service?.currentSessionCwd != null;

  /// The project identity label for the full chat's header (issue #225):
  /// the active session's folder basename, or the localized Personal
  /// label for unsandboxed sessions.
  String _projectLabel(AgentService? service) {
    final cwd = service?.currentSessionCwd;
    if (cwd != null) {
      final name = p.basename(cwd);
      if (name.isNotEmpty && name != '/' && name != '.') return name;
    }
    return context.l10n.sessionFolderPersonal;
  }
  // --- build -----------------------------------------------------------------

  @override
  Widget build(BuildContext context) {
    final service = _activeService;
    if (service == null) return const SizedBox.shrink();
    // Keep the interactive trio bound to the ACTIVE session's service —
    // a no-op while it is unchanged, and it moves the binding when the
    // user switches sessions (or the relay re-attaches).
    _surfaceHandlers.attach(service);
    final colors = FahColors.of(context);
    final size = MediaQuery.sizeOf(context);
    final drawerW = math.min(_drawerWidth, size.width * 0.82);
    return SafeArea(
      // Never let the panel/drawer slide under the status bar.
      bottom: false,
      // LayoutBuilder, NOT MediaQuery/view insets: the host Scaffold's
      // resizeToAvoidBottomInset shrinks the body around the keyboard, so
      // the laid-out height already excludes it — and constraint changes
      // REBUILD us, while `View.of(context)` never notifies on viewInsets
      // changes (`_ViewScope.updateShouldNotify` compares the view instance
      // only). Reading the inset statically kept the keyboard-less panel
      // height after the keyboard opened and pushed the panel header off
      // the top edge.
      child: LayoutBuilder(
        builder: (context, constraints) {
          final panelH = constraints.maxHeight * widget.panelFraction;
          _stackHeight = constraints.maxHeight;
          return AnimatedBuilder(
            animation: Listenable.merge([_panelAnim, _drawerAnim]),
            builder: (context, _) {
              final panelV = _panelAnim.value;
              final drawerV = _drawerAnim.value;
              final scrimV = math.max(panelV, drawerV);
              return Stack(
                children: [
                  // Scrim over the app grid while a layer is open; a tap on
                  // the exposed part dismisses the top layer. The bar sits
                  // ABOVE the scrim and stays interactive.
                  if (scrimV > 0)
                    Positioned.fill(
                      child: GestureDetector(
                        behavior: HitTestBehavior.opaque,
                        onTap: _onScrimTap,
                        child: ColoredBox(
                          color: Colors.black.withValues(alpha: 0.30 * scrimV),
                        ),
                      ),
                    ),
                  // The session panel slides up from the bottom and parks
                  // under the input bar (the bar overlaps its bottom edge).
                  if (panelV > 0)
                    Positioned(
                      left: 0,
                      right: 0,
                      bottom: 0,
                      height: panelH,
                      child: Transform.translate(
                        offset: Offset(0, (1 - panelV) * panelH),
                        child: _buildPanel(colors, service),
                      ),
                    ),
                  // The sessions drawer slides in from the left, under the
                  // bar. Its scrim sits ABOVE the panel: the grid-level
                  // scrim is unreachable while the panel covers it, so
                  // without this layer an outside tap would hit the panel
                  // and leave the drawer open.
                  if (drawerV > 0)
                    Positioned.fill(
                      child: GestureDetector(
                        behavior: HitTestBehavior.opaque,
                        onTap: () => unawaited(_toggleDrawer()),
                        child: ColoredBox(
                          color: Colors.black.withValues(alpha: 0.15 * drawerV),
                        ),
                      ),
                    ),
                  if (drawerV > 0)
                    Positioned(
                      left: 0,
                      top: 0,
                      bottom: 0,
                      width: drawerW,
                      child: Transform.translate(
                        offset: Offset(-(1 - drawerV) * drawerW, 0),
                        child: _buildDrawer(colors),
                      ),
                    ),
                  // The always-visible input bar — the top layer.
                  Positioned(
                    left: 0,
                    right: 0,
                    bottom: 0,
                    child: _buildBar(colors, service),
                  ),
                ],
              );
            },
          );
        },
      ),
    );
  }

  void _onScrimTap() {
    if (_drawerAnim.value > 0.5) {
      unawaited(_toggleDrawer());
    } else if (_panelAnim.value > 0.5) {
      unawaited(_closePanel());
    }
  }

  /// The docked input bar: the streaming status row (panel closed only)
  /// over the composer — one continuous surface into the home-indicator zone.
  Widget _buildBar(FahColors colors, AgentService service) {
    final panelOpen = _panelAnim.value > 0.5;
    return Container(
      key: const ValueKey('sessionChatBar'),
      decoration: BoxDecoration(
        color: colors.panelAlt.withValues(alpha: 0.97),
        border: Border(top: BorderSide(color: colors.border)),
        boxShadow: const [
          BoxShadow(
            color: Colors.black38,
            blurRadius: 12,
            offset: Offset(0, -2),
          ),
        ],
      ),
      child: Material(
        type: MaterialType.transparency,
        // Measure the natural bar height on every layout: the panel
        // transcript and the drawer list pad their bottoms by this exact
        // value, so content never hides under the floating bar.
        child: NotificationListener<SizeChangedLayoutNotification>(
          onNotification: (_) {
            // The notification fires DURING layout — defer the read.
            WidgetsBinding.instance.addPostFrameCallback(
              (_) => _measureBarHeight(),
            );
            return true;
          },
          child: SizeChangedLayoutNotifier(
            key: _barKey,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                // The streaming status row belongs to the closed-panel bar;
                // the open panel shows the progress inside the transcript.
                if (!panelOpen)
                  FaWorkBar(service: service, onExpand: expand, embedded: true),
                ChatComposer(
                  // Single ownership (issues #464/#459): docked, the
                  // FaWorkBar above owns the working state; expanded, the
                  // transcript's typing footer owns it — the composer
                  // itself never renders typing UI.
                  // The status row above appears/disappears with the panel
                  // and the streaming state — WITHOUT a stable key the
                  // column child matching would recreate the composer on
                  // every toggle, killing its FocusNode (the field lost
                  // focus right after send, forcing a re-tap per message).
                  key: const ValueKey('sessionChatComposer'),
                  service: service,
                  uploadPicker: widget.uploadPicker,
                  asr: widget.asr,
                  asrTranscriber: widget.asrTranscriber,
                  hideMicWhenNotEmpty: true,
                  // The always-visible bar must not pop the keyboard at
                  // app start — focus comes from a deliberate tap.
                  autofocus: false,
                  onSent: expand,
                  // Typing never happens blind: focusing the field opens
                  // the current session's panel right away.
                  onFocusChanged: (focused) {
                    if (focused) expand();
                  },
                  // Panel closed: the leading slot opens the sessions
                  // drawer. Panel open: null → the composer's own attach
                  // button (the "+" of the iMessage bar).
                  leadingBuilder: panelOpen
                      ? null
                      : (context) => IconButton(
                          key: const ValueKey('sessionChatDrawerButton'),
                          icon: _drawerAnim.value > 0.5
                              ? const Icon(Icons.close)
                              : SessionsGlyph(
                                  color: colors.dim,
                                  background: colors.panelAlt,
                                ),
                          tooltip: context.l10n.sidebarSessionsHeader,
                          onPressed: () => unawaited(_toggleDrawer()),
                        ),
                ),
                // The composer's own SafeArea lifts the field above the home
                // indicator; the bar's panel color runs through the
                // indicator zone — one continuous surface.
              ],
            ),
          ),
        ),
      ),
    );
  }

  /// The session panel: drag handle + header (draggable), divider, and the
  /// active session's transcript padded above the floating bar.
  Widget _buildPanel(FahColors colors, AgentService service) {
    final activeId = widget.manager.activeId ?? '';
    return Container(
      key: const ValueKey('sessionChatPanel'),
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        color: colors.panelAlt.withValues(alpha: 0.97),
        borderRadius: const BorderRadius.vertical(top: Radius.circular(16)),
        border: Border(top: BorderSide(color: colors.border)),
        boxShadow: const [
          BoxShadow(
            color: Colors.black38,
            blurRadius: 12,
            offset: Offset(0, -2),
          ),
        ],
      ),
      child: Material(
        type: MaterialType.transparency,
