/// One session's transcript inside the panel: the shared [ChatMessageTile]
/// renderer, pinned to the tail on new content.
class _SessionTranscript extends StatefulWidget {
  const _SessionTranscript({
    super.key,
    required this.service,
    this.onAuthRecovery,
    this.bottomPadding = 0,
    this.audioControllerFactory,
    this.videoControllerFactory,
  });

  final AgentService service;

  /// Auth-expired card action (CodeMie SSO session died): re-runs the
  /// platform sign-in flow — on the extension it opens the CodeMie login
  /// tab and polls the shared cookie jar back to life.
  final FaAuthRecoveryCallback? onAuthRecovery;

  /// Extra bottom clearance lifting the messages above the floating input
  /// bar that overlaps the panel's bottom edge.
  final double bottomPadding;

  final SandboxAudioControllerFactory? audioControllerFactory;
  final SandboxVideoControllerFactory? videoControllerFactory;

  @override
  State<_SessionTranscript> createState() => _SessionTranscriptState();
}

class _SessionTranscriptState extends State<_SessionTranscript>
    with AutomaticKeepAliveClientMixin {
  final _scrollController = ScrollController();

  /// Loads sandbox images referenced from Markdown through the session's
  /// env (memoized — see [SandboxImageResolver]).
  SandboxImageResolver? _sandboxImages;

  SandboxImageResolver get _images {
    final env = widget.service.env;
    final resolver = _sandboxImages;
    if (resolver == null || resolver.env != env) {
      return _sandboxImages = SandboxImageResolver(env);
    }
    return resolver;
  }

  @override
  void initState() {
    super.initState();
    widget.service.addListener(_scrollToEnd);
    // First build (e.g. the panel just opened): land on the LATEST
    // message, not the top of the transcript.
    WidgetsBinding.instance.addPostFrameCallback((_) => _scrollToEnd());
  }

  @override
  void dispose() {
    widget.service.removeListener(_scrollToEnd);
    _scrollController.dispose();
    super.dispose();
  }

  /// New transcript content keeps the view pinned to the latest message —
  /// with `reverse: true` that is the list's START (min extent), not its end.
  void _scrollToEnd() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_scrollController.hasClients) return;
      final position = _scrollController.position;
      if (position.pixels > position.minScrollExtent) {
        position.jumpTo(position.minScrollExtent);
      }
    });
  }

  @override
  bool get wantKeepAlive => true;

  @override
  Widget build(BuildContext context) {
    super.build(context);
    final theme = Theme.of(context);
    final colors = FahColors.of(context);
    return ListenableBuilder(
      listenable: widget.service,
      builder: (context, _) {
        final messages = widget.service.messages;
        // The single transient status row lives IN the list (issues #459,
        // #1042): the visually-LAST item — the reversed list renders it
        // right above the input bar — replaced by the assistant message on
        // completion. Empty transcript + streaming: it is the only item
        // (E1).
        final streaming = widget.service.isStreaming;
        // Only the LIVE thinking block animates (issue #1374 AC4) —
        // computed once per transcript pass, identity-matched per tile.
        final liveThinking = liveThinkingMessage(widget.service);
        if (messages.isEmpty && !streaming) {
          return Center(
            child: Padding(
              padding: EdgeInsets.fromLTRB(
                24,
                24,
                24,
                24 + widget.bottomPadding,
              ),
              child: Text(
                context.l10n.launcherChatEmptyHint,
                textAlign: TextAlign.center,
                style: theme.textTheme.bodySmall?.copyWith(color: colors.dim),
              ),
            ),
          );
        }
        return ListView.builder(
          // Tests target the transcript's scrollable through this key (the
          // fa_chat_screen 'faChatTranscriptList' pattern).
          key: const ValueKey('sessionTranscriptList'),
          controller: _scrollController,
          // reverse: content stays pinned to the BOTTOM (the input bar) — a
          // short transcript no longer flies up and out of view when the
          // keyboard opens and shrinks the viewport.
          reverse: true,
          padding: EdgeInsets.fromLTRB(12, 12, 12, 8 + widget.bottomPadding),
          itemCount: messages.length + (streaming ? 1 : 0),
          itemBuilder: (context, index) {
            // The status row is the visually-LAST entry (issue #1042): in
            // this reversed list index 0 is the bottom edge — right above
            // the input bar. The keep-alive wrapper preserves the row's
            // State (phase ticker + elapsed clock) while the item is
            // scrolled out of the list's cache extent: scrolling back must
            // not reset the elapsed seconds (PR #1082 review). The item
            // only exists while the run streams, so the keep-alive is
            // bounded by the run.
            if (streaming && index == 0) {
              return _KeepAliveStatusRow(service: widget.service);
            }
            // Slot 0 is the newest message; while streaming the status row
            // occupies slot 0 and the messages shift down by one.
            final messageIndex =
                messages.length - 1 - (streaming ? index - 1 : index);
            final message = messages[messageIndex];
            return ChatMessageTile(
              message: message,
              images: _images,
              compact: true,
              onAuthRecovery: widget.onAuthRecovery,
              messageFontSize: ChatTextScope.maybeOf(context)?.fontSize,
              audioControllerFactory: widget.audioControllerFactory,
              videoControllerFactory: widget.videoControllerFactory,
              // Only the LIVE thinking block animates (issue #1374 AC4):
              // the transcript's NEWEST thinking message; finished
              // thinking notes keep a frozen face. Identity holds — the
              // message IS a service.messages element.
              thinkingLive: identical(message, liveThinking),
              // The launcher panel never mounts a ChatScreen, so it wires
              // its own widget-tile builder (issue #336): without one the
              // live widget degrades to the plain tool card.
              dynamicWidgetTileBuilder: (context, message) => DynamicWidgetTile(
                service: widget.service.dynamicMessages,
                message: message,
                // Issue #457 AC3: the launcher panel graduates through the
                // shared helper — no greyed-out "Save as app" here.
                onSaveAsApp: (definition) =>
                    graduateDynamicWidget(context, widget.service, definition),
              ),
            );
          },
        );
      },
    );
  }
}

