/// The sessions-list glyph: a deck of two chat bubbles — a dimmer one
/// behind, the current conversation in front with a speech tail and two
/// text lines. Used wherever a "list of sessions" affordance appears (the
/// input bar's drawer toggle, the panel header). Deliberately NOT a stock
/// list/forum icon.
class SessionsGlyph extends StatelessWidget {
  const SessionsGlyph({
    super.key,
    required this.color,
    required this.background,
    this.size = 22,
  });

  /// The stroke color of the front bubble and typing dots.
  final Color color;

  /// The fill of the front bubble — pass the surface the glyph sits on so
  /// the back bubble's edge does not show through.
  final Color background;

  final double size;

  @override
  Widget build(BuildContext context) {
    return CustomPaint(
      size: Size.square(size),
      painter: _SessionsGlyphPainter(color, background),
    );
  }
}

class _SessionsGlyphPainter extends CustomPainter {
  const _SessionsGlyphPainter(this.color, this.background);

  final Color color;
  final Color background;

  @override
  void paint(Canvas canvas, Size size) {
    // Issue #462, approved variant A4b «Modern pair + dots»: a front
    // typing bubble (three dots) over a half-visible back bubble — drawn
    // on a 24x24 design grid, scaled to the requested size.
    canvas.save();
    canvas.scale(size.width / 24);
    // Shared stroke spec of the bar-icon pass (#459 attach, #426
    // subagent): 2px on the 24 grid, round caps and joins.
    final back = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round
      ..color = color.withValues(alpha: 0.55);
    // The back bubble: a dimmer outline peeking out top-right, half
    // hidden once the front bubble (filled with the surface color) lands
    // on top of it.
    canvas.drawRRect(
      RRect.fromRectAndRadius(
        const Rect.fromLTWH(9.2, 2.6, 12.2, 9.8),
        const Radius.circular(4.2),
      ),
      back,
    );
    final stroke = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round
      ..color = color;
    // The front bubble: filled first so it reads as ON TOP of the pair.
    final front = RRect.fromRectAndRadius(
      const Rect.fromLTWH(4.6, 5.6, 14.8, 9.8),
      const Radius.circular(4.2),
    );
    canvas.drawRRect(front, Paint()..color = background);
    canvas.drawRRect(front, stroke);
    // Speech tail, bottom-left of the front bubble; the endpoints tuck
    // under the bubble's own bottom stroke.
    canvas.drawPath(
      Path()
        ..moveTo(8.6, 15.2)
        ..lineTo(6.9, 19.1)
        ..lineTo(12.7, 15.2),
      stroke,
    );
    // Three typing dots, centered in the bubble.
    final dots = Paint()..color = color;
    for (final x in const [8.8, 12.0, 15.2]) {
      canvas.drawCircle(Offset(x, 10.5), 0.6, dots);
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(_SessionsGlyphPainter old) =>
      old.color != color || old.background != background;
}

/// The mobile trajectory ledger page (issue #168): the shared fa_ui
/// [TrajectoryScreen] over a page-owned [TrajectoryController]
/// subscribed to the ACTIVE session's snapshot stream. The page listens
/// to the manager, so a session switch while it stays open re-binds to
/// the newly active session's ledger (pinned E2 choice: follow, don't
/// close). The feed is a broadcast stream replaying the latest snapshot,
/// so a page opened mid-run renders the run in progress and live turns
/// keep arriving without manual refresh.
class _SessionTrajectoryPage extends StatefulWidget {
  const _SessionTrajectoryPage({required this.manager});

  final FlutterSessionManager manager;

  @override
  State<_SessionTrajectoryPage> createState() => _SessionTrajectoryPageState();
}

class _SessionTrajectoryPageState extends State<_SessionTrajectoryPage> {
  TrajectoryController? _controller;
  StreamSubscription<TrajectorySnapshot>? _subscription;
  AgentService? _service;
  bool _loaded = false;

  @override
  void initState() {
    super.initState();
    widget.manager.addListener(_onManagerChanged);
    final service = widget.manager.active?.service;
    if (service != null) _bind(service);
  }

  @override
  void dispose() {
    widget.manager.removeListener(_onManagerChanged);
    _subscription?.cancel();
    _controller?.dispose();
    super.dispose();
  }

  void _onManagerChanged() {
    final service = widget.manager.active?.service;
    if (service == null || service == _service) return;
    _bind(service);
    setState(() {});
  }

  /// (Re)binds to [service]: fresh controller + subscription, so no
  /// scroll/selection/filter state leaks across sessions. The previous
  /// controller is disposed post-frame — the in-flight build may still
  /// render it until [TrajectoryScreen.didUpdateWidget] detaches.
  void _bind(AgentService service) {
    _service = service;
    _subscription?.cancel();
    final old = _controller;
    _controller = TrajectoryController();
    _loaded = false;
    _subscription = service.trajectory.listen(_onSnapshot);
    if (old != null) {
      WidgetsBinding.instance.addPostFrameCallback((_) => old.dispose());
    }
  }

  void _onSnapshot(TrajectorySnapshot snapshot) {
    _controller?.updateSnapshot(snapshot);
    if (_loaded) return;
    _loaded = true;
    if (mounted) setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final controller = _controller;
    if (controller == null) {
      // No active session left; the header entry is guarded, so this
      // only renders a transient frame — pop straight back.
      return const Scaffold(body: SizedBox.shrink());
    }
    return TrajectoryScreen(
      controller: controller,
      loaded: _loaded,
      onClose: () => Navigator.of(context).pop(),
    );
  }
}

