  Future<void> _refreshInstalled() async {
    try {
      final apps = await _appsStore.listApps();
      // A broken app is not a usable install: excluding it from the
      // version map keeps the Install/Update buttons honest instead of
      // deriving a fake "1.0.0" from the degraded model (issue #866).
      _installed = {
        for (final app in apps)
          if (app.error == null) app.id: app.version,
      };
      _localApps = apps;
    } on Object {
      _installed = {};
      _localApps = const [];
    }
  }

  Future<void> _reload() async {
    setState(() => _loading = true);
    await _refreshInstalled();
    try {
      final result = await _catalog.fetchCatalog();
      if (mounted) {
        setState(() {
          _result = result;
          _loadError = null;
          _loading = false;
        });
      }
    } on Object catch (error) {
      if (mounted) {
        setState(() {
          _loadError = error;
          _loading = false;
        });
      }
    }
  }

  /// Installs [entry]; returns true on success.
  Future<bool> _install(CatalogEntry entry) async {
    if (_installing.contains(entry.id)) return false;
    setState(() => _installing.add(entry.id));
    AppAnalytics.instance.widgetEvent(
      'install_start',
      params: {'id': entry.id, 'sizeBytes': entry.zipSizeBytes},
    );
    final watch = Stopwatch()..start();
    try {
      // Healing variant: a cached catalog can reference release bytes a
      // later publish replaced — refetch + retry once on a hash mismatch.
      final files = await _catalog.downloadWidgetHealing(entry);
      await _appsStore.installWidget(
        id: entry.id,
        version: entry.version,
        files: files,
      );
      AppAnalytics.instance.widgetEvent(
        'install_done',
        params: {'id': entry.id, 'durationMs': watch.elapsedMilliseconds},
      );
      // See _remove: the grid needs an explicit fsRevision bump for
      // UI-side writes.
      widget.manager?.active?.service.fsRevision.value++;
      await _refreshInstalled();
      if (mounted) setState(() => _installing.remove(entry.id));
      return true;
    } on Object catch (error) {
      AppLog.i('apps', 'widget install failed: ${entry.id} — $error');
      AppAnalytics.instance.widgetEvent(
        'install_fail',
        params: {
          'id': entry.id,
          'durationMs': watch.elapsedMilliseconds,
          'errorClass': error.runtimeType.toString(),
        },
      );
      if (mounted) {
        setState(() => _installing.remove(entry.id));
        showFahErrorSnack(
          context,
          context.l10n.widgetsCatalogInstallFailed('$error'),
        );
      }
      return false;
    }
  }

  /// Removes a downloaded widget (code files go, `storage.json` survives)
  /// and refreshes the button states.
  Future<void> _remove(String id) async {
    AppAnalytics.instance.widgetEvent('remove', params: {'id': id});
    final removed = await _appsStore.removeWidget(id, force: true);
    // The launcher's grid reloads on fsRevision — which only AGENT tool
    // writes bump; UI-side mutations raise it themselves.
    widget.manager?.active?.service.fsRevision.value++;
    if (!mounted) return;
    if (removed) {
      await _refreshInstalled();
      setState(() {});
    } else {
      showFahErrorSnack(context, context.l10n.commonError);
    }
  }

  /// Opens the installed widget through the same [pushJsApp] navigation the
  /// launcher uses (or the [WidgetsCatalogSheet.onOpenApp] hook in tests).
  Future<void> _open(CatalogEntry entry) async {
    final apps = await _appsStore.listApps();
    JsAppInfo? app;
    for (final candidate in apps) {
      if (candidate.id == entry.id) app = candidate;
    }
    if (app == null) {
      if (mounted) {
        showFahErrorSnack(context, context.l10n.widgetsCatalogNotInstalled);
      }
      return;
    }
    await _launchApp(app, entry.id);
  }

  /// Shared open path for catalog entries and created-on-device apps.
  Future<void> _launchApp(JsAppInfo app, String analyticsId) async {
    // Same broken-app guard as every launch surface (issue #866): the
    // copyable dialog replaces a silently-degraded launch.
    if (await guardBrokenApp(context, app)) return;
    AppAnalytics.instance.widgetEvent(
      'open',
      params: {'id': analyticsId, 'source': 'catalog'},
    );
    if (!mounted) return;
    final hook = widget.onOpenApp;
    if (hook != null) {
      await hook(context, app);
      return;
    }
    final manager = widget.manager;
    if (manager == null) return;
    await pushJsApp(context, manager: manager, app: app, source: 'catalog');
  }

  /// Try-before-you-decide: install (when missing/outdated) then open
  /// immediately — the macOS/iOS counterpart of the website's Preview.
  Future<void> _preview(CatalogEntry entry) async {
    final installed = _installed[entry.id];
    final needsInstall =
        installed == null || semverNewer(installed, entry.version);
    if (needsInstall) {
      AppAnalytics.instance.widgetEvent(
        'preview_install',
        params: {'id': entry.id},
      );
      final ok = await _install(entry);
      if (!ok) return;
    } else {
      AppAnalytics.instance.widgetEvent('preview', params: {'id': entry.id});
    }
    await _open(entry);
  }

  Future<String?> _loadIcon(CatalogEntry entry) {
    return _iconFutures[entry.id] ??= () async {
      final icon = entry.iconFile;
      if (icon == null || icon.isEmpty) return null;
      try {
        final response = await (widget.httpClient ?? http.Client()).get(
          Uri.parse('${kDefaultWidgetsRawBaseUrl}widgets/${entry.id}/$icon'),
        );
        if (response.statusCode != 200) return null;
        return utf8.decode(response.bodyBytes);
      } on Object {
        return null;
      }
    }();
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    if (widget.embedded) {
      // Inline host (launcher tab): no sheet chrome, the body scrolls
      // with its own controller.
      return _buildBody(theme, ScrollController());
    }
    return DraggableScrollableSheet(
      expand: false,
      initialChildSize: 0.85,
      maxChildSize: 0.95,
      builder: (context, scrollController) => Column(
        children: [
          // Drag handle + title row, the same chrome the sessions sheet uses.
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
            child: Row(
              children: [
                Expanded(
                  child: Text(
                    'Widgets catalog',
                    style: theme.textTheme.titleMedium,
                  ),
                ),
                IconButton(
                  icon: const Icon(Icons.close),
                  onPressed: () => Navigator.of(context).pop(),
                ),
              ],
            ),
          ),
          const Divider(height: 1),
          Expanded(child: _buildBody(theme, scrollController)),
        ],
      ),
    );
  }

  Widget _buildBody(ThemeData theme, ScrollController scrollController) {
    if (_loading) {
      return const Center(child: CircularProgressIndicator());
    }
    if (_loadError != null) {
      return _ErrorView(error: _loadError!, onRetry: _reload);
    }
    final result = _result!;
    if (result.entries.isEmpty) {
      return Center(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Text(
            'The catalog is empty right now.',
            style: theme.textTheme.bodyMedium,
          ),
        ),
      );
    }
    return Column(
      children: [
        if (result.stale)
          Material(
            color: theme.colorScheme.errorContainer.withValues(alpha: 0.25),
            child: ListTile(
              dense: true,
              leading: const Icon(Icons.cloud_off, size: 20),
              title: Text(
                context.l10n.widgetsCatalogOffline,
                style: const TextStyle(fontSize: 13),
              ),
              trailing: TextButton(
                onPressed: _reload,
                child: Text(context.l10n.widgetsCatalogRetry),
              ),
            ),
          ),
        _buildTagFilter(theme, result),
        Expanded(
          child: ListView(
            controller: scrollController,
            children: [
              ..._buildCreatedByMe(theme, result),
              for (final entry in _filteredEntries(result))
                _CatalogTile(
                  entry: entry,
                  busy: _installing.contains(entry.id),
                  installedVersion: _installed[entry.id],
                  iconFuture: _loadIcon(entry),
                  onInstall: () => _install(entry),
                  onOpen: () => _open(entry),
                  onPreview: () => _preview(entry),
                  onRemove: () => _remove(entry.id),
                  // Issue #1045 AC3: tapping a row opens the widget's
                  // detail sheet (info + live publish status).
                  onTap: () => _showStatusDetail(
                    id: entry.id,
                    title: entry.displayName(
                      Localizations.localeOf(context).toLanguageTag(),
                    ),
                    version: entry.version,
                    description: entry.displayDescription(
                      Localizations.localeOf(context).toLanguageTag(),
                    ),
                    author: entry.author,
                  ),
                ),
            ],
          ),
        ),
      ],
    );
  }

  /// Opens the per-widget status detail sheet (issue #1045 AC3): widget
  /// info + live publish status with the validator's verbatim errors.
  void _showStatusDetail({
    required String id,
    required String title,
    String? version,
    String? description,
    String? author,
  }) {
    unawaited(
      showWidgetStatusDetailSheet(
        context,
        widgetId: id,
        title: title,
        version: version,
        description: description,
        author: author,
        env: widget.env,
      ),
    );
  }

  /// Catalog entries matching the active [_tagFilter] (null = all).
  List<CatalogEntry> _filteredEntries(CatalogFetchResult result) {
    final tag = _tagFilter;
    if (tag == null) return result.entries;
    return [
      for (final entry in result.entries)
        if (entry.tags.contains(tag)) entry,
    ];
  }

  /// Horizontally scrollable category chips: All + the sorted union of
  /// every widget's tags. Collapses to nothing for a tag-less catalog.
  Widget _buildTagFilter(ThemeData theme, CatalogFetchResult result) {
    final tags = <String>{
      for (final entry in result.entries) ...entry.tags,
    }.toList()..sort();
    if (tags.isEmpty) return const SizedBox.shrink();
    return SizedBox(
      height: 44,
      child: ListView(
        scrollDirection: Axis.horizontal,
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
        children: [
          Padding(
            padding: const EdgeInsets.only(right: 8),
            child: FilterChip(
              label: Text(context.l10n.widgetsCatalogFilterAll),
              selected: _tagFilter == null,
              showCheckmark: false,
              visualDensity: VisualDensity.compact,
              onSelected: (_) => setState(() => _tagFilter = null),
            ),
          ),
          for (final tag in tags)
            Padding(
              padding: const EdgeInsets.only(right: 8),
              child: FilterChip(
                label: Text(tag),
                selected: _tagFilter == tag,
                showCheckmark: false,
                visualDensity: VisualDensity.compact,
                onSelected: (selected) =>
                    setState(() => _tagFilter = selected ? tag : null),
              ),
            ),
        ],
      ),
    );
  }

  /// Local apps that are NOT in the catalog — widgets the agent built on
  /// this device (or side-loaded ones). Listed above the catalog with
  /// Open/Remove actions; hidden when empty.
  List<Widget> _buildCreatedByMe(ThemeData theme, CatalogFetchResult result) {
    final catalogIds = {for (final entry in result.entries) entry.id};
    final mine = [
      for (final app in _localApps)
        if (!catalogIds.contains(app.id)) app,
    ];
    if (mine.isEmpty) return const [];
    final locale = Localizations.localeOf(context).toLanguageTag();
    return [
      Padding(
        padding: const EdgeInsets.fromLTRB(16, 12, 16, 4),
        child: Text(
          context.l10n.appsCatalogCreatedByMe,
          style: theme.textTheme.titleSmall,
        ),
      ),
      // Same visual language as the catalog rows below: framed icon,
      // name + description, two equal-width stacked action buttons —
      // the group differs only by its section header. Tapping a row
      // opens the status detail sheet (issue #1045 AC3).
      for (final app in mine)
        InkWell(
          onTap: () => _showStatusDetail(
            id: app.id,
            title: app.displayName(locale),
            version: app.version,
            description: app.displayDescription(locale),
          ),
          child: Container(
            margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: theme.colorScheme.surfaceContainerLow,
              borderRadius: BorderRadius.circular(12),
              border: Border.all(
                color: theme.colorScheme.outlineVariant.withValues(alpha: 0.6),
              ),
            ),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Container(
                  width: 40,
                  height: 40,
                  decoration: BoxDecoration(
                    color: theme.colorScheme.surface,
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(color: theme.colorScheme.outlineVariant),
                  ),
                  child: Center(
                    child: AppIcon(app: app, env: widget.env, size: 26),
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        app.displayName(locale),
                        style: theme.textTheme.titleSmall,
                        overflow: TextOverflow.ellipsis,
                      ),
                      if (app.displayDescription(locale).isNotEmpty)
                        Padding(
                          padding: const EdgeInsets.only(top: 2),
                          child: Text(
                            app.displayDescription(locale),
                            style: theme.textTheme.bodySmall,
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                          ),
                        ),
                      // Provenance (gh-1616 I3): a locally unpacked widget
                      // carries the chip; agent-created apps (no install
                      // record) render nothing.
                      if (app.installSource == UnpackedWidgetLoader.origin)
                        Padding(
                          padding: const EdgeInsets.only(top: 4),
                          child: Chip(
                            label: Text(
                              context.l10n.unpackedSourceChip,
                              style: const TextStyle(fontSize: 11),
                            ),
                            visualDensity: VisualDensity.compact,
                            padding: EdgeInsets.zero,
                            materialTapTargetSize:
                                MaterialTapTargetSize.shrinkWrap,
                          ),
                        ),
                    ],
                  ),
                ),
                const SizedBox(width: 8),
                SizedBox(
                  width: 108,
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      FilledButton.tonal(
                        onPressed: () => _launchApp(app, app.id),
                        child: const Text('Open'), // l10n:ignore
                      ),
                      OutlinedButton(
                        onPressed: () => _remove(app.id),
                        style: OutlinedButton.styleFrom(
                          visualDensity: VisualDensity.compact,
                          foregroundColor: theme.colorScheme.error,
                          padding: const EdgeInsets.symmetric(horizontal: 8),
                          minimumSize: const Size(0, 36),
                          tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                        ),
                        child: const Text(
                          'Remove',
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                        ), // l10n:ignore
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
      const Divider(height: 24),
    ];
  }
}

/// One catalog row: icon, name/version/description, permission chips and
/// the action buttons — the state button Install / Update / Open (spinner
/// while downloading+writing) plus Preview (install-if-needed + open) for
/// widgets not on the device yet, or Remove once installed and current —
/// Preview would be pointless then, Open does exactly that.
class _CatalogTile extends StatelessWidget {
  const _CatalogTile({
    required this.entry,
    required this.busy,
    required this.installedVersion,
    required this.iconFuture,
    required this.onInstall,
    required this.onOpen,
    required this.onPreview,
    required this.onRemove,
    required this.onTap,
  });

  final CatalogEntry entry;
  final bool busy;

  /// Version installed on disk; null when the widget is not installed.
  final String? installedVersion;
  final Future<String?> iconFuture;
  final VoidCallback onInstall;
  final VoidCallback onOpen;
  final VoidCallback onPreview;
  final VoidCallback onRemove;

  /// Row tap — the per-widget status detail sheet (issue #1045 AC3).
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final locale = Localizations.localeOf(context).toLanguageTag();
    final chips = <String>[
      for (final tag in entry.tags.take(2)) tag,
      if (entry.network) 'network',
      if (entry.allowedCommands.isNotEmpty) 'commands',
    ];
    final hasUpdate =
        installedVersion != null &&
        semverNewer(installedVersion!, entry.version);
    return InkWell(
      onTap: onTap,
      child: Container(
        margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
          color: theme.colorScheme.surfaceContainerLow,
          borderRadius: BorderRadius.circular(12),
          border: Border.all(
            color: theme.colorScheme.outlineVariant.withValues(alpha: 0.6),
          ),
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _CatalogIcon(entry: entry, iconFuture: iconFuture),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    '${entry.displayName(locale)}  ·  v${entry.version}',
                    style: theme.textTheme.titleSmall,
                    overflow: TextOverflow.ellipsis,
                  ),
                  if (entry.displayDescription(locale).isNotEmpty)
                    Padding(
                      padding: const EdgeInsets.only(top: 2),
                      child: Text(
                        entry.displayDescription(locale),
                        style: theme.textTheme.bodySmall,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                  if (chips.isNotEmpty || entry.platforms.isNotEmpty)
                    Padding(
                      padding: const EdgeInsets.only(top: 4),
                      child: Wrap(
                        spacing: 6,
                        children: [
                          for (final chip in chips)
                            Chip(
                              label: Text(
                                chip,
                                style: const TextStyle(fontSize: 11),
                              ),
                              visualDensity: VisualDensity.compact,
                              padding: EdgeInsets.zero,
                              materialTapTargetSize:
                                  MaterialTapTargetSize.shrinkWrap,
                            ),
                          // Platform tags are compatibility info, not topics:
                          // always shown, outlined in the tertiary accent.
                          for (final platform in entry.platforms)
                            Chip(
                              label: Text(
                                platform,
                                style: TextStyle(
                                  fontSize: 11,
                                  color: theme.colorScheme.tertiary,
                                ),
                              ),
                              side: BorderSide(
                                color: theme.colorScheme.tertiary,
                              ),
                              visualDensity: VisualDensity.compact,
                              padding: EdgeInsets.zero,
                              materialTapTargetSize:
                                  MaterialTapTargetSize.shrinkWrap,
                            ),
                        ],
                      ),
                    ),
                ],
              ),
            ),
            const SizedBox(width: 8),
            // Two equal-width stacked buttons: the primary action on top,
            // the secondary (Preview / Remove) as a compact outline under
            // it — no ragged text links hanging off the button's edge.
            SizedBox(
              width: 108,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  FilledButton.tonal(
                    onPressed: busy
                        ? null
                        : (installedVersion == null || hasUpdate)
                        ? onInstall
                        : onOpen,
                    child: busy
                        ? const SizedBox(
                            width: 16,
                            height: 16,
                            child: CircularProgressIndicator(strokeWidth: 2),
                          )
                        : Text(
                            installedVersion == null
                                ? 'Install'
                                : hasUpdate
                                ? 'Update'
                                : 'Open',
                          ),
                  ),
                  const SizedBox(height: 6),
                  if (installedVersion != null && !hasUpdate)
                    // Installed & current: Preview == Open, so the secondary
                    // action is Remove instead.
                    // Text-only + maxLines 1: icon+label OutlinedButtons
                    // wrapped ("Remo / ve") inside the 108px column at the
                    // user's system text scale.
                    OutlinedButton(
                      onPressed: busy ? null : onRemove,
                      style: OutlinedButton.styleFrom(
                        foregroundColor: theme.colorScheme.error,
                        side: BorderSide(
                          color: theme.colorScheme.error.withValues(alpha: 0.4),
                        ),
                        visualDensity: VisualDensity.compact,
                        padding: const EdgeInsets.symmetric(horizontal: 6),
                        minimumSize: const Size(0, 36),
                        tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                      ),
                      child: const Text(
                        'Remove',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                      ), // l10n:ignore
                    )
                  else
                    OutlinedButton(
                      onPressed: busy ? null : onPreview,
                      style: OutlinedButton.styleFrom(
                        visualDensity: VisualDensity.compact,
                        padding: const EdgeInsets.symmetric(horizontal: 6),
                        minimumSize: const Size(0, 36),
                        tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                      ),
                      child: const Text(
                        'Preview',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                      ), // l10n:ignore
                    ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

/// The tile's leading icon: the widget's SVG from the fa_widgets raw mirror
/// when the manifest declares one; the first name letter as the fallback
/// (same look the tile had before icons loaded).
class _CatalogIcon extends StatelessWidget {
  const _CatalogIcon({required this.entry, required this.iconFuture});

  final CatalogEntry entry;
  final Future<String?> iconFuture;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    if (entry.iconFile == null || entry.iconFile!.isEmpty) {
      return _fallback(Localizations.localeOf(context).toLanguageTag());
    }
    return FutureBuilder<String?>(
      future: iconFuture,
      builder: (context, snapshot) => _iconTile(context, theme, snapshot),
    );
  }

  /// The SVG tile for a loaded icon; the letter fallback while loading or
  /// when the markup is blank (gh-1848 split). The SVG sits in a neutral
  /// rounded tile: widgets whose icon is a bare glyph (crypto's ₿) get a
  /// proper frame instead of floating naked next to the colored icons.
  Widget _iconTile(
    BuildContext context,
    ThemeData theme,
    AsyncSnapshot<String?> snapshot,
  ) {
    final markup = snapshot.data;
    if (markup == null || markup.trim().isEmpty) return _fallback();
    return Container(
      width: 40,
      height: 40,
      decoration: BoxDecoration(
        color: theme.colorScheme.surface,
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: theme.colorScheme.outlineVariant),
      ),
      child: Center(
        child: SizedBox(
          width: 26,
          height: 26,
          child: SvgPicture.string(markup, fit: BoxFit.contain),
        ),
      ),
    );
  }

  /// Deterministic accent per widget id — the SVG tiles each have their
  /// own color, and a bare letter on the washed-out default CircleAvatar
  /// looked broken next to them.
  static const _palette = [
    Color(0xFF4F46E5),
    Color(0xFF0D9488),
    Color(0xFFD97706),
    Color(0xFFDC2626),
    Color(0xFF7C3AED),
    Color(0xFF2563EB),
    Color(0xFF059669),
    Color(0xFFDB2777),
  ];

  Widget _fallback([String? locale]) {
    final color = _palette[entry.id.hashCode.abs() % _palette.length];
    final label = entry.displayName(locale);
    return Container(
      width: 34,
      height: 34,
      decoration: BoxDecoration(
        color: color,
        borderRadius: BorderRadius.circular(9),
      ),
      child: Center(
        child: Text(
          label.isEmpty ? '?' : label.characters.first.toUpperCase(),
          style: const TextStyle(
            color: Colors.white,
            fontWeight: FontWeight.w700,
            fontSize: 15,
          ),
        ),
      ),
    );
  }
}

class _ErrorView extends StatelessWidget {
  const _ErrorView({required this.error, required this.onRetry});

  final Object error;
  final VoidCallback onRetry;

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Padding(
        padding: const EdgeInsets.all(24),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Icon(Icons.cloud_off),
            const SizedBox(height: 8),
            Text(
              context.l10n.widgetsCatalogLoadFailed(error.toString()),
              textAlign: TextAlign.center,
              style: Theme.of(context).textTheme.bodySmall,
            ),
            const SizedBox(height: 12),
            OutlinedButton(
              onPressed: onRetry,
              child: Text(context.l10n.widgetsCatalogRetry),
            ),
          ],
        ),
      ),
    );
  }
}

